const evidence=[];function scan(dir,prefix=''){for(const e of fs.readdirSync(dir,{withFileTypes:true})){assert(!e.isSymbolicLink());const file=dir+'/'+e.name,p=prefix+e.name;if(e.isDirectory())scan(file,p+'/');else evidence.push({file,path:p,bytes:fs.statSync(file).size,sha256:hash(file)});}}scan(base,'browser/');for(const name of ['baseline-v2','baseline-v3','candidate']){const root=base+'/'+name;const b=json(root+'/BUILD.json'),start=json(root+'/browser/STARTED.json'),end=json(root+'/browser/TERMINAL.json');assert.equal(start.pid,end.pid);assert.equal(end.code,0);assert.equal(start.componentSha256,b.componentSha256);for(const r of b.inputs)assert.equal(hash(r.path),r.sha256);for(const r of b.files)assert.equal(hash(root+'/'+r.name),r.sha256);if(name==='baseline-v2')assert.equal(hash(root+'/ENTRY.before-capability.raw'),b.fixtureSourceSha256);else assert.equal(hash('review-pager-focus-browser-20261024.tsx'),b.fixtureSourceSha256);}
